import {proposalCover,openProposal} from './proposals.js';
// Workspace is a view/controller over the original Project, Direction and Asset models.
export function mountWorkspace(api){
 const {project:p,save,esc,analyzeBrief,createDirections,refineDirection,generateCampaign,visual,moodboard,openAsset,download}=api;
 p.workspace??={messages:[],positions:{},selection:[],view:{x:30,y:55,z:.7}};
 const w=p.workspace;w.positions??={};w.selection??=[];w.view??={x:30,y:55,z:.7};let pending=false,disposed=false,closeProposal=()=>{};
 const sampleText="我们下个月要推出这款便携咖啡机，主要在社媒和电商推广。我喜欢 Fellow 对产品设计的重视、Aesop 克制的高级感，以及 Patagonia 自由探索的感觉。";
 const isSample=p.brand==='NOMA';
 if(!w.messages.length&&isSample){w.messages.push({role:'user',text:sampleText},{role:'agent',text:'NOMA 的设计很克制，但打动人的地方是随时随地喝咖啡的自由。我会围绕这两个特点，探索三个创意方向。'});}
 const root=document.querySelector('main');root.className='workspace';root.innerHTML=`<aside class="chat-panel"><div class="chat-heading"><span class="spark">✳</span><div><h3>创意搭档</h3><span class="muted">聊聊想法，一起找到方向。</span></div><span class="tag">演示版 0.2</span></div><div id="conversation" aria-live="polite"></div><div class="composer-wrap"><div id="context-chips"></div><form id="chat-form"><textarea id="chat-input" aria-label="发送创作需求" placeholder="聊聊你的产品、推广目标，或先放一张图片、一个参考链接。"></textarea><div class="compose-actions"><label class="attach">+ 产品图<input type="file" id="ws-product" multiple accept="image/jpeg,image/png,image/webp"></label><label class="attach">+ 参考图<input type="file" id="ws-reference" multiple accept="image/jpeg,image/png,image/webp"></label><button class="primary" id="send" aria-label="发送消息">↑</button></div></form><p class="input-hint">回车发送 · Shift＋回车换行</p><p class="demo-note">本地演示 · 理解与生成采用模拟逻辑</p></div></aside><section class="canvas-pane"><div class="canvas-toolbar"><div><strong>${esc(p.brand||'未命名项目')}</strong><span class="muted"> / 创意画布</span></div><div class="row"><button data-focus="sources">参考素材</button><button data-focus="insight">创意洞察</button><button data-focus="directions">创意方向</button><button data-focus="outputs">生成素材</button></div></div><div id="viewport" tabindex="0" aria-label="创意画布。拖动空白处平移，Shift 加点击多选卡片，使用按钮缩放。"><div id="world"></div><div class="canvas-empty" id="canvas-empty"><span class="spark">✳</span><h2>这次想做什么？</h2><p>放一张产品图、一个参考，或聊聊还没成形的想法。<br>我们一起找到创作方向。</p></div></div><div class="canvas-footer"><span>拖动卡片 · Shift＋点击多选 · 滚轮平移</span><div class="row"><button id="zoom-out" aria-label="缩小">−</button><span id="zoom-label"></span><button id="zoom-in" aria-label="放大">+</button><button id="fit">查看全貌</button><button id="download" ${p.assets?.length?'':'disabled'}>下载素材 ↓</button></div></div></section>`;
 const $=s=>root.querySelector(s);let nodes=[];
 function message(text,role='agent',context=[]){w.messages.push({role,text,context});save();paintChat()}
 function paintChat(){const list=$('#conversation');if(!list)return;list.innerHTML=w.messages.length?w.messages.map(m=>`<div class="message ${m.role}"><div class="label">${m.role==='agent'?'✳ Forma':'你'}</div><p>${esc(m.text)}</p>${m.context?.length?`<div class="message-context">参考：${m.context.map(esc).join(' · ')}</div>`:''}</div>`).join(''):`<div class="chat-welcome"><div class="eyebrow">从一个想法开始</div><h2>这次想做什么？</h2><p class="muted">一句想法、一张产品图、一个链接，都可以开始。不用先整理成完整需求。</p></div>`;if(pending)list.innerHTML+='<div class="message agent working" role="status">✳ 正在整理你的创作线索…</div>';list.scrollTop=list.scrollHeight;$('#send').disabled=pending;paintContext()}
 function paintContext(){w.selection=w.selection.filter(id=>nodes.some(n=>n.id===id));$('#context-chips').innerHTML=w.selection.length?`<div class="label">本次参考：</div><div class="chips">${w.selection.map(id=>`<button type="button" data-clear="${id}" class="chip">${esc(nodes.find(n=>n.id===id).label)} ×</button>`).join('')}</div>`:'';root.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{w.selection=w.selection.filter(id=>id!==b.dataset.clear);selectionChanged()})}
 function selectionChanged(){root.querySelectorAll('.canvas-node').forEach(el=>{el.classList.toggle('is-selected',w.selection.includes(el.dataset.node));el.setAttribute('aria-pressed',String(w.selection.includes(el.dataset.node)))});paintContext();save()}
 function node(id,label,x,y,body,kind='source'){nodes.push({id,label,x,y,body,kind})}
 function buildNodes(){nodes=[];const images=p.images?.length?p.images:isSample?['/assets/b.png']:[];images.forEach((img,i)=>node('product-'+i,i?'产品 '+(i+1):'产品',30,70+i*390,`<img class="source-photo" src="${esc(img)}" alt="产品"><div class="node-body"><div class="label">产品</div><h3>${esc((p.brand?p.brand+' ':'')+(p.product||'你的产品'))}</h3></div>`));let ry=70+images.length*390;(p.references||[]).forEach((url,i)=>{let host;try{host=new URL(url).hostname.replace(/^www\./,'')}catch{host=url}const name=host.includes('fellowproducts')?'Fellow':host.includes('aesop')?'Aesop':host.includes('patagonia')?'Patagonia':host.split('.')[0];node('ref-'+i,'参考：'+name,30,ry+i*175,`<div class="node-body"><div class="label">网站参考</div><h3>${esc(name.charAt(0).toUpperCase()+name.slice(1))} ↗</h3><a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(host)}</a></div>`)});(p.referenceImages||[]).forEach((img,i)=>node('reference-image-'+i,'参考图片 '+(i+1),30,ry+(p.references||[]).length*175+i*350,`<img class="source-photo" src="${esc(img)}" alt="参考图片"><div class="node-body"><div class="label">参考图片 ${i+1}</div></div>`));
 if(p.brief){node('understanding','需求理解',390,70,`<div class="node-body"><div class="eyebrow">✳ 需求理解</div><h2>${esc(p.product||'创作需求')}</h2><div class="summary-item"><div class="label">产品理解</div><p>${esc(p.brief.product)}</p></div><div class="summary-item"><div class="label">品牌理解</div><p>${esc(p.brandDescription||p.keywords.join(' / ')||'品牌个性还可以进一步明确。')}</p></div><div class="summary-item"><div class="label">受众假设</div><p>${esc(p.brief.audience)}</p></div></div>`,'understanding');node('insight','创意洞察',390,580,`<div class="node-body"><div class="eyebrow">创意洞察 · ${isSample?'示例假设':'初步假设'}</div><h2>设计感与自由感，可以兼得。</h2>${(isSample?[['品类惯例','便携咖啡产品通常强调轻巧、方便和性能参数。'],['参考线索','Fellow → 有设计感的产品\nAesop → 克制的高级感\nPatagonia → 自由与探索'],['创意机会','让“便携”从功能卖点变成一种生活态度：无论身在何处，都拥有自己的咖啡时刻。']]:[['我们理解的需求',p.objective],['创意机会',p.brief.opportunity],['有待确认','受众与参考风格的解读还是初步假设，可以继续一起调整。']]).map(([l,t])=>`<div class="summary-item"><div class="label">${l}</div><p>${esc(t)}</p></div>`).join('')}</div>`,'insight')}
 (p.creativeDirections||[]).forEach((d,i)=>node('direction-'+d.id,'方向 0'+(i+1),820+i*375,70,proposalCover(d,i,p,esc),'direction'));
 (p.assets||[]).forEach((a,i)=>node('asset-'+a.id,a.type,2040+i%3*375,70+Math.floor(i/3)*590,`${visual(a)}<div class="node-body"><div class="label">生成素材 · V${a.versions.length}</div><h3>${esc(a.type)}</h3><p class="detail">${esc(a.expression||'围绕所选方向，展开新的视觉表达。')}</p><div class="label">${esc(a.context?.directionName||p.creativeDirections?.find(d=>d.id===a.context?.direction)?.name||'推广创作')}</div><button data-review="${a.id}">查看与修改 ↗</button></div>`,'output'));
 }
 function paintCanvas(){buildNodes();$('#canvas-empty').hidden=nodes.length>0;$('#world').innerHTML=`${nodes.length?'<div class="zone" style="left:30px">参考素材</div>':''}${p.brief?'<div class="zone" style="left:390px">需求理解与洞察</div>':''}${p.creativeDirections?.length?'<div class="zone" style="left:820px">创意方向</div>':''}${p.assets?.length?'<div class="zone" style="left:2040px">一个创意，多种表达。</div>':''}`+nodes.map(n=>{const pos=w.positions[n.id]||n;return `<article tabindex="0" role="group" aria-label="${esc(n.label)}" aria-pressed="${w.selection.includes(n.id)}" data-node="${n.id}" class="canvas-node ${n.kind} ${w.selection.includes(n.id)?'is-selected':''}" style="left:${pos.x}px;top:${pos.y}px;width:${n.kind==='direction'||n.kind==='output'?345:320}px"><div class="node-grip" title="拖动卡片">⠿ <span>${esc(n.label)}</span><button class="context-toggle" data-context="${n.id}" aria-label="将${esc(n.label)}加入本次参考">${w.selection.includes(n.id)?'✓':'+'}</button></div>${n.body}</article>`}).join('');root.querySelectorAll('.canvas-node img').forEach(img=>img.draggable=false);transform();paintContext();$('#download').disabled=!p.assets?.length;root.querySelectorAll('[data-proposal]').forEach(b=>b.onclick=()=>{const i=p.creativeDirections.findIndex(d=>d.id===b.dataset.proposal);closeProposal=openProposal({d:p.creativeDirections[i],i,p,esc,onDevelop:develop,onRefine:id=>{w.selection=['direction-'+id];selectionChanged();$('#chat-input').value='调整这个方向：';$('#chat-input').focus()}})});root.querySelectorAll('[data-develop]').forEach(b=>b.onclick=()=>develop(b.dataset.develop));root.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openAsset(b.dataset.review));root.querySelectorAll('[data-refine]').forEach(b=>b.onclick=()=>{w.selection=['direction-'+b.dataset.refine];selectionChanged();$('#chat-input').value='保留这个创意，但让视觉表达更有高级感。';$('#chat-input').focus()});root.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>{const id=b.dataset.context;w.selection=w.selection.includes(id)?w.selection.filter(x=>x!==id):[...w.selection,id];selectionChanged()});root.querySelectorAll('.canvas-node').forEach(el=>{el.onkeydown=e=>{if(e.target!==el)return;if(e.key==='Enter'){w.selection=e.shiftKey?[...new Set([...w.selection,el.dataset.node])]:[el.dataset.node];selectionChanged()}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=nodes.find(n=>n.id===el.dataset.node),pos=w.positions[n.id]??{x:n.x,y:n.y};pos.x+=e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0;pos.y+=e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0;w.positions[n.id]=pos;el.style.left=pos.x+'px';el.style.top=pos.y+'px';save()}}})}
 function transform(){if(!$('#world'))return;$('#world').style.transform=`translate(${w.view.x}px,${w.view.y}px) scale(${w.view.z})`;$('#zoom-label').textContent=Math.round(w.view.z*100)+'%'}
 function focusZone(zone){const locations={sources:30,insight:390,directions:820,outputs:2040};w.view={x:35-locations[zone]*.72,y:35,z:.72};transform();save()}
 function zoom(factor){const vp=$('#viewport');const cx=vp.clientWidth/2,cy=vp.clientHeight/2;const old=w.view.z,z=Math.min(1.5,Math.max(.2,old*factor));w.view.x=cx-(cx-w.view.x)*z/old;w.view.y=cy-(cy-w.view.y)*z/old;w.view.z=z;transform();save()}
 function fit(){if(!nodes.length)return;let maxX=0,maxY=0,minX=Infinity,minY=Infinity;root.querySelectorAll('.canvas-node').forEach(el=>{minX=Math.min(minX,parseFloat(el.style.left));minY=Math.min(minY,parseFloat(el.style.top));maxX=Math.max(maxX,parseFloat(el.style.left)+el.offsetWidth);maxY=Math.max(maxY,parseFloat(el.style.top)+el.offsetHeight)});const vp=$('#viewport');const z=Math.max(.2,Math.min(.9,(vp.clientWidth-60)/(maxX-minX),(vp.clientHeight-60)/(maxY-minY)));w.view={x:30-minX*z,y:30-minY*z,z};transform();save()}
 const viewport=$('#viewport');let drag=null;
 viewport.onpointerdown=e=>{if(e.button!==0||e.target.closest('button,a,input,textarea'))return;const el=e.target.closest('.canvas-node');drag={id:el?.dataset.node,startX:e.clientX,startY:e.clientY,moved:false,shift:e.shiftKey};if(el){const n=nodes.find(n=>n.id===drag.id);drag.origin={...(w.positions[n.id]||{x:n.x,y:n.y})}}else drag.origin={x:w.view.x,y:w.view.y};viewport.setPointerCapture(e.pointerId)};
 viewport.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;if(drag.id&&drag.moved){w.positions[drag.id]={x:drag.origin.x+dx/w.view.z,y:drag.origin.y+dy/w.view.z};const el=root.querySelector(`[data-node="${drag.id}"]`);el.style.left=w.positions[drag.id].x+'px';el.style.top=w.positions[drag.id].y+'px'}else if(!drag.id){w.view.x=drag.origin.x+dx;w.view.y=drag.origin.y+dy;transform()}};
 viewport.onpointerup=e=>{if(!drag)return;if(drag.id&&!drag.moved){w.selection=drag.shift?(w.selection.includes(drag.id)?w.selection.filter(x=>x!==drag.id):[...w.selection,drag.id]):[drag.id];selectionChanged()}else if(!drag.id&&!drag.moved){w.selection=[];selectionChanged()}drag=null;save()};viewport.onpointercancel=()=>{drag=null};
 viewport.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)zoom(e.deltaY<0?1.1:.9);else{w.view.x-=e.deltaX;w.view.y-=e.deltaY;transform();save()}},{passive:false});
 $('#zoom-in').onclick=()=>zoom(1.2);$('#zoom-out').onclick=()=>zoom(1/1.2);$('#fit').onclick=fit;root.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focusZone(b.dataset.focus));$('#download').onclick=download;
 async function work(fn){if(pending)return;pending=true;paintChat();try{await fn();save();if(!disposed)paintCanvas()}catch(e){message('刚才处理没有成功，已保留你的创作线索，请再试一次。')}finally{pending=false;if(!disposed)paintChat()}}
 async function understand(){p.brief=await analyzeBrief(p);if(disposed)return;paintCanvas();await new Promise(r=>setTimeout(r,450));if(disposed)return;p.creativeDirections=await createDirections(p);p.creativeDirections.forEach((d,i)=>d.builtFrom=isSample?['Patagonia 的自由感 ＋ NOMA 的便携特性。','Fellow 的产品设计感 ＋ Aesop 克制的高级感。','自由探索的生活态度 ＋ 不止于功能的大胆表达。'][i]:['产品的日常价值 ＋ 受众真实的使用时刻。','产品设计线索 ＋ 细腻的产品叙事。','推广目标 ＋ 更有表现力的视觉语言。'][i]);message('我已整理好需求，并在画布上展开三个创意方向。你可以选一个生成素材，也可以告诉我想组合哪些特点。');paintCanvas();focusZone('directions')}
 async function develop(id){return work(async()=>{const d=p.creativeDirections.find(d=>d.id===id);p.selectedDirection=id;const assets=await generateCampaign(p);if(p.assets?.length){assets.forEach(a=>a.id+='-'+crypto.randomUUID().slice(0,8))}p.assets=[...(p.assets||[]),...assets];message(`已将“${d.name}”展开为三种表达：产品主视觉、材质近景和日常生活场景，共享同一个创意方向。`);paintCanvas();focusZone('outputs')})}
 async function submit(text){if(!text.trim()||pending)return;const ids=[...w.selection],contexts=ids.map(id=>nodes.find(n=>n.id===id)?.label).filter(Boolean);message(text,'user',contexts);$('#chat-input').value='';w.draft='';await work(async()=>{const urls=text.match(/https?:\/\/[^\s<>]+/g)||[];p.references=[...new Set([...(p.references||[]),...urls.map(u=>u.replace(/[.,，。)]+$/,''))])];if(/another.*(?:kv|hero)|再.*(?:主视觉|KV)/i.test(text)){const d=p.creativeDirections?.find(d=>ids.includes('direction-'+d.id))||p.creativeDirections?.find(d=>d.id===p.selectedDirection);if(!d){message('请先在画布上选中一个创意方向，再让我生成一张主视觉。');return}const previous=p.selectedDirection;p.selectedDirection=d.id;const a=(await generateCampaign(p))[0];p.selectedDirection=previous||d.id;a.id='kv-'+crypto.randomUUID().slice(0,8);a.type='新增主视觉';a.context.selectedObjects=ids;a.context.request=text;a.context.directionName=d.name;a.versions[0].scale=1.12;a.expression='另一种主视觉构图 · 已记录所选参考对象';p.assets=[...(p.assets||[]),a];message(`已围绕“${d.name}”新增一张主视觉。本次参考：${contexts.join(', ')||d.name}。演示版采用本地构图，暂不分析参考图片内容。`);paintCanvas();focusZone('outputs');return}
 if(p.creativeDirections?.length&&/premium|combine|mix|like the idea|高级|温暖|简约|组合|融合|保留.*创意|调整.*方向|refine|this concept/i.test(text)){const id=ids.find(id=>id.startsWith('direction-'))?.slice(10)||(/coffee anywhere|随行咖啡时刻/i.test(text)?'a':p.selectedDirection||'a');const d=p.creativeDirections.find(d=>d.id===id);Object.assign(d,await refineDirection(d,text));d.builtFrom='“随行咖啡时刻”的自由感 ＋ “为日常仪式而设计”的克制高级感。';message(`已更新画布上的“${d.name}”：保留创意，调整视觉表达。已有素材保持原样；点击“用这个方向生成素材”，就能得到新的一组。`);paintCanvas();focusZone('directions');return}
 if(p.creativeDirections?.length&&/develop|展开|生成素材/i.test(text)){const d=p.creativeDirections.find(d=>ids.includes('direction-'+d.id))||p.creativeDirections.find(d=>d.id===p.selectedDirection);if(!d){message('请先选中一个方向，或直接点击卡片上的“用这个方向生成素材”。');return}p.selectedDirection=d.id;const assets=await generateCampaign(p);if(p.assets?.length)assets.forEach(a=>a.id+='-'+crypto.randomUUID().slice(0,8));p.assets=[...(p.assets||[]),...assets];message(`已将“${d.name}”展开为三种推广素材。`);paintCanvas();focusZone('outputs');return}
 if(!p.brief){if(!isSample){const coffee=/coffee|咖啡/i.test(text);p.product=coffee?'便携咖啡机':text.replace(/https?:\/\/\S+/g,'').trim().slice(0,75)||'新产品';p.brand=/noma/i.test(text)?'NOMA':p.brand||'你的品牌';p.description=text;p.objective=text;p.audience=p.audience||'受众待明确（初步假设）';p.keywords=/premium|aesop|高级/i.test(text)?['高级','简约']:['独立'];p.sellingPoints=coffee?'轻巧便携\n随时享用咖啡':'产品卖点待明确';p.constraints=[];}message('我先把你提供的线索整理成初步需求，再探索几个创意方向。这些是演示版的初步假设，你可以随时调整。');await understand()}else{p.contextNotes=[...(p.contextNotes||[]),text];message(urls.length?'已将链接添加为参考素材。可以和创意方向一起选中，作为本次参考。演示版暂不读取网页内容。':'已记下你的补充。可以选中一个方向，让我调整视觉风格；也可以选中几张卡片，说“参考这些，再生成一张主视觉”。');}})}
 $('#chat-input').value=w.draft||'';$('#chat-input').oninput=e=>{w.draft=e.target.value;save()};
 $('#chat-form').onsubmit=e=>{e.preventDefault();submit($('#chat-input').value)};$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();submit(e.target.value)}};
 async function upload(files,key){if(files.length>4||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){message('每次最多添加 4 张 JPG、PNG 或 WebP 图片，每张不超过 5 MB。');return}const imgs=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})));p[key]=[...(p[key]||[]),...imgs];save();paintCanvas();message(`已添加 ${imgs.length} 张${key==='images'?'产品':'参考'}图片。聊聊你想用它们做什么。`);focusZone('sources')}
 $('#ws-product').onchange=e=>upload([...e.target.files],'images');$('#ws-reference').onchange=e=>upload([...e.target.files],'referenceImages');viewport.ondragover=e=>e.preventDefault();viewport.ondrop=e=>{e.preventDefault();if(e.dataTransfer.files.length)upload([...e.dataTransfer.files],'referenceImages');else{const t=e.dataTransfer.getData('text/plain');if(t)submit(t)}};
 paintCanvas();paintChat();save();if(isSample&&!p.brief)work(understand);else if(isSample&&!p.creativeDirections?.length)work(understand);
 return ()=>{disposed=true;closeProposal()};
}
